#include <unistd.h>
#include <cstddef>
#include <iostream>
int main(){std::size_t pages{};std::cin>>pages;const auto pageSize=static_cast<std::size_t>(sysconf(_SC_PAGESIZE));const auto bytes=pages*pageSize;void* mapping=mmap(nullptr,bytes,PROT_READ|PROT_WRITE,MAP_PRIVATE|MAP_ANON,-1,0);if(mapping==MAP_FAILED){std::cout<<"mapping=failed\n";return 0;}auto* memory=static_cast<volatile unsigned char*>(mapping);std::size_t touched=0;for(std::size_t index=0;index<pages;++index){memory[index*pageSize]=static_cast<unsigned char>(index);++touched;}munmap(mapping,bytes);std::cout<<"pages="<<pages<<" touched="<<touched<<"\n";}

